IF EXISTS(SELECT 1 FROM @Map m WHERE NOT EXISTS(SELECT 1 FROM CM_Cust c WHERE c.CorpId=''1000'' AND c.CustCode=m.CustCode) OR NOT EXISTS(SELECT 1 FROM CM_Item i WHERE i.CorpId=''1000'' AND i.ItemCode=m.ItemCode)) THROW 50000,N''코드 검증 실패'',1;
UPDATE a SET CustCode=m.CustCode,ItemCode=m.ItemCode
FROM PM_ForecastOrderActual a JOIN @Map m ON m.ChannelName=a.ChannelName AND m.ItemName=a.ItemName WHERE a.CorpId=''1000'';
SELECT CorpId,CustCode,ItemCode,OrderDate,MIN(ChannelName) ChannelName,MIN(ItemName) ItemName,CONVERT(int,SUM(CONVERT(bigint,OrderQty))) OrderQty
INTO #Merged FROM PM_ForecastOrderActual
WHERE CorpId=''1000'' AND CustCode IS NOT NULL AND ItemCode IS NOT NULL
GROUP BY CorpId,CustCode,ItemCode,OrderDate;
DELETE FROM PM_ForecastOrderActual WHERE CorpId=''1000'' AND CustCode IS NOT NULL AND ItemCode IS NOT NULL;
INSERT PM_ForecastOrderActual(CorpId,CustCode,ItemCode,OrderDate,ChannelName,ItemName,OrderQty)
SELECT CorpId,CustCode,ItemCode,OrderDate,ChannelName,ItemName,OrderQty FROM #Merged;
IF ISNULL(@Before,0)<>ISNULL((SELECT SUM(CONVERT(bigint,OrderQty)) FROM PM_ForecastOrderActual WHERE CorpId=''1000''),0) THROW 50000,N''발주량 합계 불일치'',1;
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE object_id=OBJECT_ID(''dbo.PM_ForecastOrderActual'') AND name=''UX_ForecastActual_Codes'')
 CREATE UNIQUE INDEX UX_ForecastActual_Codes ON dbo.PM_ForecastOrderActual(CorpId,CustCode,ItemCode,OrderDate) WHERE CustCode IS NOT NULL AND ItemCode IS NOT NULL;
-- 실 발주 품목 중 거래처별 품목 관리에 없는 연결 추가
INSERT dbo.CM_ItemPrice(CorpId,CustCode,ItemCode,PriceType,Price,ApplyDate,ChannelName,ForecastItemName,UseYn,CreId,CreDt)
SELECT DISTINCT a.CorpId,a.CustCode,a.ItemCode,''20'',NULL,CONVERT(date,GETDATE()),c.CustName,i.ItemName,''Y'',N''개발자'',GETDATE()
FROM PM_ForecastOrderActual a JOIN CM_Cust c ON c.CorpId=a.CorpId AND c.CustCode=a.CustCode
JOIN CM_Item i ON i.CorpId=a.CorpId AND i.ItemCode=a.ItemCode
WHERE a.CorpId=''1000'' AND NOT EXISTS(SELECT 1 FROM CM_ItemPrice p WHERE p.CorpId=a.CorpId AND p.CustCode=a.CustCode AND p.ItemCode=a.ItemCode AND p.PriceType=''20'');
');
EXEC(N'
IF EXISTS(SELECT 1 FROM PM_ForecastOrderActual WHERE CustCode IS NULL OR ItemCode IS NULL) THROW 50000,N''미연결 실 발주량 존재'',1;
IF EXISTS(SELECT 1 FROM sys.indexes WHERE object_id=OBJECT_ID(''dbo.PM_ForecastOrderActual'') AND name=''UX_ForecastActual_Codes'') DROP INDEX UX_ForecastActual_Codes ON dbo.PM_ForecastOrderActual;
ALTER TABLE dbo.PM_ForecastOrderActual ALTER COLUMN CustCode nvarchar(20) NOT NULL;
ALTER TABLE dbo.PM_ForecastOrderActual ALTER COLUMN ItemCode nvarchar(200) NOT NULL;
DECLARE @Pk sysname=(SELECT name FROM sys.key_constraints WHERE parent_object_id=OBJECT_ID(''dbo.PM_ForecastOrderActual'') AND type=''PK'');
IF @Pk IS NOT NULL BEGIN DECLARE @Drop nvarchar(500)=''ALTER TABLE dbo.PM_ForecastOrderActual DROP CONSTRAINT ''+QUOTENAME(@Pk); EXEC(@Drop); END;
IF EXISTS(SELECT 1 FROM sys.indexes WHERE object_id=OBJECT_ID(''dbo.PM_ForecastOrderActual'') AND name=''UX_ForecastActual_Codes'') DROP INDEX UX_ForecastActual_Codes ON dbo.PM_ForecastOrderActual;
ALTER TABLE dbo.PM_ForecastOrderActual ADD CONSTRAINT PK_PM_ForecastOrderActual PRIMARY KEY(CorpId,CustCode,ItemCode,OrderDate);
');
COMMIT;
